- اگر جواب‌ها خیلی طولانی شدند max-height کافی نیست؛ آن موقع از ترفند `grid-template-rows: 0fr → 1fr` استفاده کن.

سیستم تب با data attribute:

```html
<!DOCTYPE html>
<html lang='fa' dir='rtl'>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width, initial-scale=1.0'>
<title>تب‌ها</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; font-family: Tahoma, sans-serif; }
  body { background: #f5f6fa; padding: 40px 16px; }
  .tabs { max-width: 560px; margin: auto; background: #fff; border-radius: 14px; overflow: hidden; box-shadow: 0 3px 12px rgba(0,0,0,.07); }
  .tab-btns { display: flex; border-bottom: 1px solid #eee; }
  .tab-btns button { flex: 1; padding: 14px; border: 0; background: none; font-family: inherit; font-size: 15px; cursor: pointer; color: #777; border-bottom: 2px solid transparent; }
  .tab-btns button.active { color: #1668dc; border-bottom-color: #1668dc; font-weight: bold; }
  .panel { display: none; padding: 22px; font-size: 14px; line-height: 2; color: #444; }
  .panel.active { display: block; }
</style>
</head>
<body>
  <div class='tabs'>
    <div class='tab-btns'>
      <button data-tab='p1' class='active'>توضیحات</button>
      <button data-tab='p2'>مشخصات</button>
      <button data-tab='p3'>نظرات</button>
    </div>
    <div class='panel active' id='p1'>این محصول با بهترین کیفیت تولید شده و شامل ۱۸ ماه گارانتی معتبر است.</div>
    <div class='panel' id='p2'>وزن: ۲۵۰ گرم | باتری: ۴۰ ساعت | اتصال: بلوتوث ۵.۳ | رنگ: مشکی</div>
    <div class='panel' id='p3'>۴.۶ از ۵ ⭐ (۳۲۴ دیدگاه) — کیفیت صدا عالیه و باتری واقعا دووم داره!</div>
  </div>
<script>
  const btns = document.querySelectorAll('.tab-btns button');
  const panels = document.querySelectorAll('.panel');

  btns.forEach(btn => {
    btn.addEventListener('click', () => {
      btns.forEach(b => b.classList.remove('active'));
      panels.forEach(p => p.classList.remove('active'));
      btn.classList.add('active');
      document.querySelector('#' + btn.dataset.tab).classList.add('active');
    });
  });
</script>
</body>
</html>
```

نکته معماری: اتصال دکمه به پنل با `data-tab` انجام می‌شود نه با ترتیب آرایه‌ها؛ به این ترتیب اگر فردا ترتیب دکمه‌ها را عوض کنی هیچ‌چیز نمی‌شکند. همین الگو با Event Delegation روی `.tab-btns` هم قابل پیاده‌سازی است که برای تب‌های زیاد تمیزتر است. برای دسترس‌پذیری کامل، نقش‌های ARIA مثل `role='tablist'` و `aria-selected` را هم اضافه کن.

مودال با overlay و سه روش بستن:

```html
<!DOCTYPE html>
<html lang='fa' dir='rtl'>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width, initial-scale=1.0'>
<title>مودال</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; font-family: Tahoma, sans-serif; }
  body { padding: 40px; }
  .open-btn { padding: 11px 26px; border: 0; border-radius: 8px; background: #1668dc; color: #fff; font-size: 15px; cursor: pointer; }
  .overlay { position: fixed; inset: 0; background: rgba(0,0,0,.5); display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity .25s, visibility .25s; z-index: 100; }
  .overlay.show { opacity: 1; visibility: visible; }
  .modal { position: relative; background: #fff; border-radius: 14px; padding: 28px; width: min(420px, 90vw); text-align: center; transform: translateY(20px); transition: transform .25s; }
  .overlay.show .modal { transform: translateY(0); }
  .modal h2 { font-size: 18px; margin-bottom: 10px; }
  .modal p { font-size: 14px; color: #666; line-height: 2; margin-bottom: 20px; }
  .close { padding: 9px 30px; border: 0; border-radius: 8px; background: #eef2f7; cursor: pointer; font-family: inherit; }
  .x { position: absolute; top: 12px; left: 14px; background: none; border: 0; font-size: 22px; cursor: pointer; color: #999; }
</style>
</head>
<body>
  <button class='open-btn' id='openBtn'>باز کردن مودال</button>
  <div class='overlay' id='overlay'>
    <div class='modal'>
      <button class='x' id='xBtn' aria-label='بستن'>×</button>
      <h2>حذف حساب کاربری</h2>
      <p>آیا مطمئن هستید؟ این عمل قابل بازگشت نیست و همه داده‌های شما حذف می‌شود.</p>
      <button class='close' id='cancelBtn'>انصراف</button>
    </div>
  </div>
<script>
  const overlay = document.querySelector('#overlay');

  document.querySelector('#openBtn').addEventListener('click', () => {
    overlay.classList.add('show');
    document.querySelector('#cancelBtn').focus();
  });
  document.querySelector('#xBtn').addEventListener('click', close);
  document.querySelector('#cancelBtn').addEventListener('click', close);

  // کلیک روی خود overlay (نه داخل مودال) → بستن
  overlay.addEventListener('click', e => {
    if (e.target === overlay) close();
  });

  // کلید Escape
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && overlay.classList.contains('show')) close();
  });

  function close() {
    overlay.classList.remove('show');
  }
</script>
</body>
</html>
```

نکات حرفه‌ای:
- چک `e.target === overlay` لازم است چون کلیک داخل مودال هم با Bubbling به overlay می‌رسد و نباید مودال بسته شود.
- انیمیشن با opacity + visibility انجام شده؛ visibility باعث می‌شود بعد از محو شدن، مودال کلیک‌ها را نگیرد.
- هنگام باز شدن فوکوس روی دکمه انصراف می‌رود تا کاربر کیبوردی گم نشود؛ برای دسترس‌پذیری کامل، فوکوس را هنگام بستن به دکمه بازکردن برگردان.
- z-index: 100 روی overlay تضمین می‌کند روی همه محتوا بیاید.

کرونومتر دقیق با محاسبه مبتنی بر timestamp (بدون خطای انباشته):

```html
<!DOCTYPE html>
<html lang='fa' dir='rtl'>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width, initial-scale=1.0'>
<title>کرونومتر</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { min-height: 100vh; display: flex; align-items: center; justify-content: center; background: #111; }
  .box { text-align: center; }
  #display { color: #0f0; font-size: 56px; letter-spacing: 2px; direction: ltr; font-family: monospace; }
  .btns { margin-top: 24px; display: flex; gap: 12px; justify-content: center; }
  button { padding: 11px 26px; border: 0; border-radius: 8px; font-size: 15px; cursor: pointer; font-family: Tahoma; }
  #startBtn { background: #2e7d32; color: #fff; }
  #stopBtn { background: #e53935; color: #fff; }
  #resetBtn { background: #555; color: #fff; }
  button:disabled { opacity: .4; cursor: not-allowed; }
</style>
</head>
<body>
  <div class='box'>
    <div id='display'>00:00.00</div>
    <div class='btns'>
      <button id='startBtn'>شروع</button>
      <button id='stopBtn' disabled>توقف</button>
      <button id='resetBtn'>ریست</button>
    </div>
  </div>
<script>
  const display = document.querySelector('#display');
  const startBtn = document.querySelector('#startBtn');
  const stopBtn = document.querySelector('#stopBtn');
  const resetBtn = document.querySelector('#resetBtn');

  let startTime = 0;   // timestamp لحظه شروع
  let accumulated = 0; // زمان جمع‌شده قبل از آخرین توقف
  let rafId = null;

  function format(ms) {
    const m = Math.floor(ms / 60000);
    const s = Math.floor((ms % 60000) / 1000);
    const cs = Math.floor((ms % 1000) / 10);
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
  }

  function tick() {
    display.textContent = format(accumulated + (Date.now() - startTime));
    rafId = requestAnimationFrame(tick);
  }

  startBtn.addEventListener('click', () => {
    startTime = Date.now();
    rafId = requestAnimationFrame(tick);
    startBtn.disabled = true;
    stopBtn.disabled = false;
  });

  stopBtn.addEventListener('click', () => {
    accumulated += Date.now() - startTime;
    cancelAnimationFrame(rafId);
    startBtn.disabled = false;
    stopBtn.disabled = true;
  });

  resetBtn.addEventListener('click', () => {
    cancelAnimationFrame(rafId);
    accumulated = 0;
    display.textContent = '00:00.00';
    startBtn.disabled = false;
    stopBtn.disabled = true;
  });
</script>
</body>
</html>
```

چرا این روش دقیق است؟
- به‌جای شمارش تیک‌ها (که خطا انباشته می‌کند) زمان از اختلاف `Date.now()` محاسبه می‌شود؛ حتی اگر تب مدتی فریز شود عدد درست می‌ماند.
- به‌جای setInterval از `requestAnimationFrame` استفاده شده که با نرخ رفرش مانیتور همگام است و پرش نمی‌زند.
- `padStart(2, '0')` اعداد را همیشه دورقمی نگه می‌دارد تا عرض نمایش ثابت بماند و ارقام نپرند.
- دکمه‌ها با disabled از اجرای همزمان دو state جلوگیری می‌کنند (مثلا دوبار زدن شروع).
- برای ادامه بعد از توقف، startTime دوباره ست می‌شود و زمان قبلی در accumulated جمع می‌شود — همان الگوی کرونومترهای واقعی.

فرم ثبت‌نام با اعتبارسنجی زنده (Live Validation):

```html
<!DOCTYPE html>
<html lang='fa' dir='rtl'>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width, initial-scale=1.0'>
<title>ثبت‌نام</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; font-family: Tahoma, sans-serif; }
  body { min-height: 100vh; display: flex; align-items: center; justify-content: center; background: #f0f2f5; }
  form { background: #fff; padding: 30px; border-radius: 14px; width: min(400px, 92vw); box-shadow: 0 4px 20px rgba(0,0,0,.08); }
  h1 { font-size: 19px; margin-bottom: 20px; text-align: center; }
  input { width: 100%; padding: 11px; border: 1.5px solid #ddd; border-radius: 8px; margin-bottom: 6px; font-size: 14px; font-family: inherit; }
  input.valid { border-color: #2e7d32; }
  input.invalid { border-color: #e53935; }
  .hint { font-size: 12px; min-height: 16px; margin-bottom: 10px; color: #999; }
  .hint.ok { color: #2e7d32; }
  .hint.bad { color: #e53935; }
  .bar { height: 5px; background: #eee; border-radius: 4px; margin-bottom: 16px; overflow: hidden; }
  .bar div { height: 100%; width: 0; background: #e53935; transition: width .3s, background .3s; }
  button { width: 100%; padding: 12px; border: 0; border-radius: 8px; background: #1668dc; color: #fff; font-size: 15px; cursor: pointer; font-family: inherit; }
  button:disabled { background: #b7cbe8; cursor: not-allowed; }
</style>
</head>
<body>
  <form id='signup' novalidate>
    <h1>ساخت حساب کاربری</h1>
    <input name='email' type='email' placeholder='ایمیل'>
    <p class='hint' data-hint='email'></p>
    <input name='password' type='password' placeholder='رمز عبور'>
    <div class='bar'><div id='strength'></div></div>
    <input name='confirm' type='password' placeholder='تکرار رمز عبور'>
    <p class='hint' data-hint='confirm'></p>
    <button type='submit' id='submitBtn' disabled>ثبت‌نام</button>
  </form>
<script>
  const form = document.querySelector('#signup');
  const strengthBar = document.querySelector('#strength');
  const submitBtn = document.querySelector('#submitBtn');
  const state = { email: false, password: false, confirm: false };

  function setHint(name, ok, text) {
    const hint = form.querySelector(`.hint[data-hint='${name}']`);
    hint.textContent = text;
    hint.className = 'hint ' + (ok ? 'ok' : 'bad');
    form.elements[name].classList.toggle('valid', ok);
    form.elements[name].classList.toggle('invalid', !ok);
    state[name] = ok;
    submitBtn.disabled = !(state.email && state.password && state.confirm);
  }

  function passwordScore(v) {
    let s = 0;
    if (v.length >= 8) s++;
    if (v !== v.toLowerCase() && v !== v.toUpperCase()) s++; // ترکیب حروف بزرگ و کوچک
    if (/[0-9]/.test(v)) s++;          // رقم دارد
    if (/[^a-zA-Z0-9]/.test(v)) s++;   // کاراکتر خاص دارد
    return s;
  }

  form.elements.email.addEventListener('input', e => {
    const v = e.target.value.trim();
    const ok = v.includes('@') && v.includes('.') && v.indexOf('@') < v.lastIndexOf('.');
    setHint('email', ok, ok ? 'ایمیل معتبر است' : 'فرمت ایمیل درست نیست');
  });

  form.elements.password.addEventListener('input', e => {
    const v = e.target.value;
    const score = passwordScore(v);
    const colors = ['#e53935', '#ff9800', '#ffc107', '#8bc34a', '#2e7d32'];
    strengthBar.style.width = score * 25 + '%';
    strengthBar.style.background = colors[score];
    setHint('password', v.length >= 8, v.length >= 8 ? 'رمز مناسب است' : 'حداقل ۸ کاراکتر لازم است');
    checkConfirm();
  });

  function checkConfirm() {
    const v = form.elements.confirm.value;
    const ok = v.length > 0 && v === form.elements.password.value;
    setHint('confirm', ok, ok ? 'رمزها یکسان هستند' : 'تکرار رمز با رمز یکسان نیست');
  }
  form.elements.confirm.addEventListener('input', checkConfirm);

  form.addEventListener('submit', e => {
    e.preventDefault();
    alert('ثبت‌نام با موفقیت انجام شد ✓');
  });
</script>
</body>
</html>
```

نکات پیاده‌سازی:
- رویداد `input` (نه change) برای بازخورد زنده استفاده شده؛ change فقط بعد از خروج از فیلد می‌آید.
- passwordScore چهار معیار را می‌سنجد: طول، ترکیب حروف بزرگ/کوچک، رقم و کاراکتر خاص؛ نتیجه در نوار رنگی با ۵ سطح نمایش داده می‌شود.
- دکمه ثبت تا معتبر شدن هر سه فیلد `disabled` است؛ این الگو خطاهای ارسال را تقریبا به صفر می‌رساند.
- وقتی رمز عوض می‌شود، تکرار رمز هم دوباره چک می‌شود چون ممکن است حالا دیگر تطابق نداشته باشد.
- در پروژه واقعی اعتبارسنجی سمت سرور هم الزامی است چون JS به‌راحتی دور زده می‌شود.

